appearances.css:
.__body{font-size:9px}
.device{padding:6px;gap:4px;border-radius:4px;display:flex;flex-direction:column}
.device>*{min-width:0}
header{padding:0 2px 3px;gap:4px 10px}
.transport{gap:4px 10px}
button{font-size:9px;padding:3px 6px;letter-spacing:.04em;border-radius:3px}
button.fill{min-width:0;padding:3px 10px}
.tp{gap:3px;font-size:8px;letter-spacing:.04em}
.tp input[type=range]{width:60px}
.tracks{grid-template-columns:repeat(6,minmax(0,1fr));gap:3px}
.trk{grid-template-columns:12px minmax(0,1fr) 20px;gap:3px;padding:2px 3px;min-height:26px;border-radius:3px}
.trk .num{font-size:7.5px}
.trk .nm{font-size:8.5px;letter-spacing:0}
.trk .nm small{display:none}
.trk button.m{width:20px;height:18px;font-size:8px}
.display{padding:3px 6px;gap:2px 8px;border-radius:4px}
.display .big{font-size:12px;letter-spacing:.06em}
.display .sub{display:none}
.display .lockinfo{min-height:0;font-size:8px}
.display .machine label{display:none}
.display .machine select{font-size:9px;padding:2px 3px}
.display .pages{padding-top:3px;gap:3px;flex-wrap:nowrap}
.pages button{min-width:0;padding:3px 2px}
.pages button.lk{min-width:0;flex:1 1 0}
.knobs{grid-template-columns:repeat(8,minmax(0,1fr));gap:2px;padding:4px 4px 3px;border-radius:4px}
.knob{display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;align-items:start;gap:0;min-width:0}
.knob .lab{display:contents}
.knob .lab span{order:3;font-size:7px;letter-spacing:-.02em;text-align:center;line-height:1.1;max-width:100%;text-transform:none;white-space:normal;overflow:hidden}
.knob .lab output{order:2;font-size:8px;line-height:1.1;text-align:center;white-space:nowrap;letter-spacing:-.04em;max-width:100%}
.knob>.kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
.trigs{grid-template-columns:repeat(16,minmax(0,1fr));gap:2px}
.trig{aspect-ratio:auto;height:30px;padding:0 0 2px;gap:1px;border-radius:2px}
.trig .n{font-size:8px}
.trig .led{height:4px}
.trig .flag{top:1px;font-size:7px}
.stepbar{display:flex;flex-wrap:wrap;gap:2px 6px;padding:4px 5px;border-radius:4px;align-items:flex-end;justify-content:space-between}
.stepbar .f{display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;align-items:start;gap:0;font-size:7px;letter-spacing:0;text-transform:none;flex:1 1 0;min-width:0}
.stepbar .f.three,.stepbar .f.three[style]{grid-template-columns:minmax(0,1fr)!important;grid-column:auto!important}
.stepbar .f>span{order:3;text-align:center;line-height:1.1}
.stepbar .f>output{order:2;font-size:8px;line-height:1.1;text-align:center;min-width:0}
.stepbar .f>.kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
.stepbar .f>select{order:1;width:100%;font-size:8.5px;padding:3px 0;text-align:center;text-align-last:center;appearance:none;-webkit-appearance:none}
.side{display:flex;flex-wrap:wrap;gap:4px}
.side>.panel{padding:4px 5px;gap:3px;border-radius:4px;flex:1 1 100%}
.panel h2{display:none}
.side>.panel:nth-child(1){display:flex;flex-wrap:wrap;align-items:flex-end}
.side>.panel:nth-child(1)>.pats:not(.actions){flex:1 1 100%}
.pats{gap:2px}
.pats button{min-width:0;padding:3px 0;font-size:9px}
.pats.actions button{padding:3px 5px;font-size:8.5px;letter-spacing:0}
.side>.panel:nth-child(1)>.pats.actions{flex:1 1 auto}
.side>.panel:nth-child(1)>.row:not(.wide){flex:0 0 52px}
.side>.panel:nth-child(1)>.row.wide{flex:1 1 120px}
.row{display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;align-items:start;gap:0}
.row label{order:3;font-size:7px;letter-spacing:0;text-transform:none;text-align:center;white-space:normal;line-height:1.1}
.row output{order:2;font-size:8px;line-height:1.1;text-align:center;white-space:nowrap}
.row>.kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
.row>select{order:1;width:100%;font-size:8.5px;padding:3px 0;text-align:center;text-align-last:center;appearance:none;-webkit-appearance:none}
.row.wide{display:grid;grid-template-columns:minmax(0,1fr)}
.row.wide label{order:2}
.chain{letter-spacing:.1em;font-size:9px;padding:3px 4px}
.side>.panel:nth-child(2){display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:2px}
.side>.panel:nth-child(3){display:flex;flex-wrap:wrap;gap:3px;align-items:center}
.side>.panel:nth-child(3)>*{flex:1 1 auto}
details summary{font-size:8.5px}
.kn svg{width:100%;height:100%}
.trigs{align-self:stretch}
.tp>.kn{width:26px!important;height:26px!important}
.knob .lab output,.row output,.stepbar .f>output{margin-top:1px}
